const base = String($env.NEXTJS_CONTROL_PLANE_BASE_URL || '').replace(/\/$/, '');
const prior = $json;
if (!base) {
  return [{ json: { ...prior, phase064_load: { state: 'blocked', reason: 'NEXTJS_CONTROL_PLANE_BASE_URL_MISSING' }, governance_response: null } }];
}
try {
  const response = await fetch(`${base}/api/department-governance`, { method: 'GET', headers: { accept: 'application/json' } });
  const data = await response.json().catch(() => null);
  return [{ json: { ...prior, phase064_load: { state: response.ok ? 'ready' : 'blocked', reason: response.ok ? 'GOVERNANCE_API_LOADED' : `GOVERNANCE_API_HTTP_${response.status}` }, governance_response: data } }];
} catch (error) {
  return [{ json: { ...prior, phase064_load: { state: 'blocked', reason: `GOVERNANCE_API_FETCH_FAILED:${error?.message || String(error)}` }, governance_response: null } }];
}

const j = $json;
const report = j.governance_response?.data?.phase9_validation_report;
const blocked = j.phase064_load?.state !== 'ready' || report?.state !== 'ready';
return [{ json: { ...j, workflow_064_read_only_validation: { workflow_id: '064.read_only_validation', build_order: 1, mode: 'read_only_validation', state: blocked ? 'blocked' : 'ready', reason: blocked ? (j.phase064_load?.reason || report?.reason || 'PHASE9_REPORT_NOT_READY') : 'READ_ONLY_VALIDATION_CONTRACT_READY', mutation_allowed: false, authority_granted: false, output_contract: 'PHASE9_READONLY_VALIDATION_REPORT' } } }];

const j = $json;
const orchestration = j.governance_response?.data?.phase063_workflow_orchestration;
const edges = Array.isArray(orchestration?.dry_run_edges) ? orchestration.dry_run_edges : [];
const expected = ['Marketing->Media', 'Media->Operations', 'Operations->Customer', 'Customer->Business Truth'];
const edgeLabels = edges.map((edge) => `${edge.from_department}->${edge.to_department}`);
const missing = expected.filter((label) => !edgeLabels.includes(label));
const blocked = orchestration?.state !== 'ready' || missing.length > 0;
return [{ json: { ...j, workflow_064_dry_run_orchestration: { workflow_id: '064.dry_run_orchestration', build_order: 2, mode: 'dry_run', state: blocked ? 'blocked' : 'ready', reason: blocked ? `DRY_RUN_BLOCKED:${missing.join(',') || orchestration?.reason || 'UNKNOWN'}` : 'DRY_RUN_MATCHES_CANONICAL_HANDOFFS', dry_run_edges: edges, mutation_allowed: false, authority_granted: false, output_contract: 'DRY_RUN_HANDOFF_MATCH_REPORT' } } }];

const j = $json;
const mapping = j.governance_response?.data?.phase064_n8n_workflow_contracts?.workflow_mapping || [];
const live = mapping.find((item) => item.workflow_id === '064.controlled_live_observation');
const ready = live?.state === 'ready';
return [{ json: { ...j, workflow_064_controlled_live_observation: { workflow_id: '064.controlled_live_observation', build_order: 3, mode: 'controlled_live_observation', state: ready ? 'ready' : 'blocked', reason: ready ? 'CONTROLLED_LIVE_CONTRACT_READY_BUT_NOT_ACTIVE' : 'CONTROLLED_LIVE_CONTRACT_NOT_READY', activation_status: 'BLOCKED_UNTIL_EXPLICIT_REVIEW', live_activation_allowed: false, mutation_allowed: false, authority_granted: false, input_contract: 'POST /api/runtime/execution-event', output_contract: 'PHASE4_EXECUTION_TRACE_READ_MODEL' } } }];

const j = $json;
const orchestration = j.governance_response?.data?.phase063_workflow_orchestration;
const escalations = Array.isArray(orchestration?.escalation_notices) ? orchestration.escalation_notices : [];
const stopConditions = Array.isArray(orchestration?.stop_conditions) ? orchestration.stop_conditions : [];
const triggeredStops = stopConditions.filter((condition) => condition.triggered === true);
return [{ json: { ...j, workflow_064_monitoring_escalation: { workflow_id: '064.monitoring_escalation', build_order: 4, mode: 'monitoring_escalation', state: triggeredStops.length ? 'blocked' : 'ready', reason: triggeredStops.length ? 'MONITORING_ESCALATION_STOP_CONDITION_TRIGGERED' : 'MONITORING_ESCALATION_CONTRACT_READY', escalation_notices: escalations, triggered_stop_conditions: triggeredStops, mutation_allowed: false, authority_granted: false, output_contract: 'ESCALATION_NOTICE_REPORT' } } }];

const j = $json;
const workflows = [j.workflow_064_read_only_validation, j.workflow_064_dry_run_orchestration, j.workflow_064_controlled_live_observation, j.workflow_064_monitoring_escalation];
const blocked = workflows.filter((workflow) => workflow?.state === 'blocked');
return [{ json: { ...j, phase064_import_report: { state: blocked.length ? 'blocked' : 'ready_for_review', reason: blocked.length ? 'PHASE064_IMPORT_DRAFT_BLOCKED' : 'PHASE064_IMPORT_DRAFT_READY_FOR_REVIEW', contract_version: '064.v1', active: false, mutation_allowed: false, authority_granted: false, source_of_truth_unchanged: true, live_activation_allowed: false, review_required_before_activation: true, workflows, blockers: blocked.map((workflow) => ({ workflow_id: workflow.workflow_id, reason: workflow.reason })) } } }];

const j = $json;
const base = String($env.NEXTJS_CONTROL_PLANE_BASE_URL || '').replace(/\/$/, '');
const secretAvailable = Boolean(String($env.RUNTIME_INGRESS_SECRET || '').trim());
const report = j.phase064_import_report || {};
const executionId = String($execution?.id || Date.now());
const emittedAt = new Date().toISOString();
const eventState = report.state === 'ready_for_review' ? 'succeeded' : 'blocked';
const eventType = eventState === 'succeeded' ? 'AUDIT_EVENT_RECORDED' : 'EXECUTION_BLOCKED';
const event = {
  event_id: `${executionId}_phase064_emit`,
  idempotency_key: `${executionId}_phase064_emit_once`,
  trace_id: `phase064:${executionId}`,
  workflow_run_id: executionId,
  n8n_execution_id: executionId,
  workflow_ref: $workflow?.name || '064 - N8N Workflow Build Draft',
  request_ref: 'phase064_import_draft',
  task_ref: 'phase064_contract_validation',
  event_type: eventType,
  execution_state: eventState,
  retry_state: 'not_applicable',
  actor_type: 'N8N',
  actor_ref: 'n8n:phase064:draft',
  emitted_at: emittedAt,
  payload: {
    phase: '064',
    report_state: report.state || 'blocked',
    report_reason: report.reason || 'PHASE064_REPORT_MISSING',
    contract_version: report.contract_version || '064.v1',
    active: false,
    mutation_allowed: false,
    authority_granted: false,
    live_activation_allowed: false,
    blockers: Array.isArray(report.blockers) ? report.blockers : []
  }
};
return [{ json: { ...j, phase064_emit: { state: base && secretAvailable ? 'ready' : 'skipped', reason: base ? (secretAvailable ? 'CONTROL_PLANE_EMIT_READY' : 'RUNTIME_INGRESS_SECRET_MISSING') : 'NEXTJS_CONTROL_PLANE_BASE_URL_MISSING', control_plane_url: base ? `${base}/api/runtime/execution-event` : null, active: false, mutation_allowed: false, authority_granted: false }, telemetry_event: event } }];

const j = $json;
if (j.phase064_emit?.state !== 'ready') {
  return [{ json: { ...j, phase064_emit_result: { state: 'skipped', reason: j.phase064_emit?.reason || 'EMIT_NOT_READY', active: false, mutation_allowed: false, authority_granted: false } } }];
}
let crypto;
try {
  crypto = require('crypto');
} catch (error) {
  return [{ json: { ...j, phase064_emit_result: { state: 'blocked', reason: `CRYPTO_MODULE_UNAVAILABLE:${error?.message || String(error)}`, active: false, mutation_allowed: false, authority_granted: false } } }];
}
const timestamp = Date.now().toString();
const body = JSON.stringify(j.telemetry_event);
const secret = String($env.RUNTIME_INGRESS_SECRET || '').trim();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
try {
  const response = await fetch(j.phase064_emit.control_plane_url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-runtime-event-timestamp': timestamp,
      'x-runtime-event-signature': `sha256=${signature}`
    },
    body
  });
  const responseBody = await response.json().catch(async () => ({ raw: await response.text().catch(() => '') }));
  return [{ json: { ...j, phase064_emit_result: { state: response.ok ? 'emitted' : 'blocked', reason: response.ok ? 'CONTROL_PLANE_EVENT_ACCEPTED' : `CONTROL_PLANE_EVENT_REJECTED_${response.status}`, status: response.status, response: responseBody, active: false, mutation_allowed: false, authority_granted: false } } }];
} catch (error) {
  return [{ json: { ...j, phase064_emit_result: { state: 'blocked', reason: `CONTROL_PLANE_EMIT_FAILED:${error?.message || String(error)}`, active: false, mutation_allowed: false, authority_granted: false } } }];
}
